function translateNLToSQL(nl, schema){
  // simple, parameterized template (for illustration)
  const tbl = escape(nl.table);
  const where = nl.filters ? nl.filters.map(f => `${escapeId(f.col)} = @val`).join(' AND ') : '1=1';
  return `SELECT * FROM ${tbl} WHERE ${where} LIMIT 100`;
}
